            base={'question_id':qid,'variant_id':d['variant_id'],'expected_wrong_answer':d['expected_wrong_answer'],'design_path':rel(design_path),'design_sha256':file_hash(design_path),'plugin_path':rel(v/'plugin.json'),'plugin_sha256':file_hash(v/'plugin.json'),'image_path':rel(v/'candidate.png'),'image_sha256':file_hash(v/'candidate.png'),'pixel_sha256':d['pixel_sha256'],'render_check_path':rel(v/'render_check.json'),'render_check_sha256':file_hash(v/'render_check.json'),'target_path_audit_path':rel(v/'fresh_target_path_audit.json'),'baseline_pixel_equal':rc['baseline_matches_formal'],'two_renders_byte_identical':rc['deterministic'],'schema_normalized_by_actual_PluginRenderer':True,'primary_unique_math':d['primary_unique_mathematics'],'primary_math_supplement_paths':[rel(p) for p in folder.glob('primary_*audit.json')],'marker_roles':d['marker_roles'],'original_controls':{'status':'not_run','reason':'Optional; no candidate reaches paired-hit criterion. No original accuracy or causal-effect claim is made.'},'correct_answer':AD.records[qid]['answer'],'independent_second_review':'Not performed by this worker. Parent must launch a NEW independent review before any delivery.'}
